"use strict";
import { PortfolioLogo } from "components/AccountDrawer/MiniPortfolio/PortfolioLogo";
import { ArrowUpRight } from "react-feather";
import { Button, Flex, styled, Text, useSporeColors } from "ui/src";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { NumberType, useFormatter } from "utils/formatNumbers";
import { useBorrowContext } from "../ContextProvider";
import { mockPositionData } from "../MockBorrowData";
const CardWrapper = styled(Flex, {
  flexDirection: "column",
  width: "100%",
  gap: "$spacing16"
});
const Card = styled(Flex, {
  flexDirection: "column",
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  borderWidth: 1,
  borderColor: "$surface3Hovered",
  p: "$spacing24",
  gap: "$spacing24"
});
const LabelText = styled(Text, {
  color: "$neutral2",
  variant: "body2",
  $sm: {
    variant: "body3"
  }
});
const ValueText = styled(LabelText, {
  color: "$neutral1"
});
const Divider = styled(Flex, {
  height: 1,
  width: "100%",
  backgroundColor: "$surface3"
});
const ActionButton = styled(Button, {
  borderRadius: "$roundedFull",
  py: "$spacing12"
});
const DataRow = ({ label, value, subValue }) => <Flex row justifyContent="space-between" alignItems="center" width="100%">
    <LabelText color="$neutral2">{label}</LabelText>
    <Flex row alignItems="center" gap={"$spacing8"}>
      <ValueText color="$neutral1">{value}</ValueText>
      {subValue && <Flex backgroundColor="$surface3" px="$spacing8" py="$spacing2" borderRadius="$roundedFull">
          <Text variant="body4" color="$neutral2">
            {subValue}
          </Text>
        </Flex>}
    </Flex>
  </Flex>;
const SliderTrack = styled(Flex, {
  height: 4,
  width: "100%",
  backgroundColor: "$surface3",
  borderRadius: "$roundedFull",
  position: "relative"
});
const SliderFill = styled(Flex, {
  height: "100%",
  backgroundColor: "$greenVibrant",
  // or appropriate health color
  borderRadius: "$roundedFull"
});
export default function PositionCard() {
  const { formatFiatPrice } = useFormatter();
  const colors = useSporeColors();
  const { openTransaction } = useBorrowContext();
  return <CardWrapper>
      {mockPositionData.map((position) => <Card key={position.id}>
          {
    /* Header */
  }
          <Flex row justifyContent="space-between" alignItems="center" width="100%">
            <Flex row alignItems="center" gap="$gap12">
              <Flex row alignItems="center">
                <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={position.collateral.token.symbol}
    tokenName={position.collateral.token.name}
    images={[getTokenLogoUrl(position.collateral.token.id) || void 0]}
    size={32}
  />
                <Flex style={{ marginLeft: -12 }}>
                  <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={position.loan.token.symbol}
    tokenName={position.loan.token.name}
    images={[getTokenLogoUrl(position.loan.token.id) || void 0]}
    size={32}
  />
                </Flex>
              </Flex>
              <Flex row alignItems="center" gap="$gap8">
                <LabelText color="$neutral1">
                  {position.collateral.token.symbol}/{position.loan.token.symbol}
                </LabelText>
                <Flex backgroundColor="$surface3" px="$spacing8" py="$spacing2" borderRadius="$roundedFull">
                  <Text variant="body4" color="$neutral2">
                    {position.lltv.toFixed(1)}%
                  </Text>
                </Flex>
                <ArrowUpRight size={18} color={colors.neutral2.val} />
              </Flex>
            </Flex>
            <ValueText color={"$neutral1"}>{position.rate.toFixed(2)}%</ValueText>
          </Flex>

          <Divider />

          {
    /* Stats */
  }
          <Flex flexDirection="column" gap="$gap16">
            <DataRow
    label="Collateral"
    value={`${position.collateral.amount.toFixed(2)} ${position.collateral.token.symbol}`}
    subValue={formatFiatPrice({ price: position.collateral.value, type: NumberType.FiatTokenStats })}
  />
            <DataRow
    label="Loan"
    value={`${position.loan.amount.toFixed(2)} ${position.loan.token.symbol}`}
    subValue={formatFiatPrice({ price: position.loan.value, type: NumberType.FiatTokenStats })}
  />
            <DataRow label="Utilization" value={`${position.utilization.toFixed(2)}%`} />
          </Flex>

          <Divider />

          {
    /* LTV Slider Area */
  }
          <Flex flexDirection="column" gap="$gap12">
            <SliderTrack>
              <SliderFill width="5%" /> {
    /* Mock fill based on LTV/LLTV */
  }
            </SliderTrack>
            <Flex row justifyContent="space-between">
              <LabelText>LTV: 0.00%</LabelText>
              <LabelText>LLTV: {position.lltv}%</LabelText>
            </Flex>
          </Flex>

          <Divider />

          <Flex flexDirection="row" gap="$spacing18" justifyContent="space-between">
            <ActionButton flex={1} onPress={() => openTransaction(position, "borrow")}>
              Borrow
            </ActionButton>
            <ActionButton flex={1} emphasis="secondary" onPress={() => openTransaction(position, "repay")}>
              Repay
            </ActionButton>
          </Flex>
        </Card>)}
    </CardWrapper>;
}
